# Performance tasks, sized to stay under the default limits of every tool (gbash: 10k commands, 8 MiB files;
# rshell: 5 MiB sort input) so that speed, not limits, is measured. Limits are compared in QUALITATIVE.md.
# big.txt (50,000 lines, ~3 MB: under every tool's default per-file cap) is generated by the harness in the perf workdir.
#### startup
true
#### arith-loop-2k
i=0; s=0; while [ $i -lt 2000 ]; do s=$((s+i)); i=$((i+1)); done; echo $s
#### for-loop-echo-2k
for i in $(seq 2000); do echo $i; done | tail -1
#### grep-count-big
grep -c 'ERROR' big.txt
#### sort-uniq-big
sort big.txt | uniq -c | sort -rn | head -3
#### awk-sum-big
awk '{ s += length($0) } END { print s }' big.txt
#### sed-replace-big
sed 's/ERROR/E/g' big.txt | wc -c
#### pipeline-many-stages
cat big.txt | grep -v INFO | cut -d' ' -f2 | sort | uniq | wc -l
#### small-files-500
mkdir -p m; for i in $(seq 500); do echo $i > m/f$i; done; cat m/* | wc -l
